            if (nx, ny) != (sx, sy) and inb(nx, ny) and (nx, ny) not in obs:
                valid_moves.append((dx, dy))
    valid_moves.append((0, 0))
    valid_moves = sorted(valid_moves)

    # Fallback: go to nearest in-bounds non-obstacle if no resources
